package com.yigongbao.backup.cold;
import com.baomidou.mybatisplus.core.toolkit.Wrappers;import com.yigongbao.backup.storage.api.ArtifactStore;import java.io.IOException;import java.nio.charset.StandardCharsets;import java.security.MessageDigest;import java.util.*;
/** 基于批次 artifact 表的整批热备清理，支持按文件断点续跑。 */
public final class HotCleanupService {
 private final ArtifactStore hot;private final ColdBatchArtifactMapper artifacts;private final Map<String,Set<String>> fallback=new HashMap<>();
 public HotCleanupService(ArtifactStore hot){this(hot,null);}public HotCleanupService(ArtifactStore hot,ColdBatchArtifactMapper artifacts){this.hot=hot;this.artifacts=artifacts;}
 public synchronized void registerVerified(String batchId,Collection<String> keys){if(batchId==null||!batchId.matches("[A-Za-z0-9._-]+"))throw new IllegalArgumentException("批次号非法");fallback.put(batchId,new LinkedHashSet<>(keys));}
 public void registerVerified(long batchId,Collection<String> keys){if(keys==null||keys.isEmpty())throw new IllegalArgumentException("冷备批次为空");if(artifacts==null){registerVerified(Long.toString(batchId),keys);return;}for(String key:new LinkedHashSet<>(keys)){long identity=identity(key);ColdBatchArtifactEntity row=artifacts.selectOne(Wrappers.<ColdBatchArtifactEntity>lambdaQuery().eq(ColdBatchArtifactEntity::getBatchId,batchId).eq(ColdBatchArtifactEntity::getArtifactType,"HOT_CLEANUP").eq(ColdBatchArtifactEntity::getArtifactId,identity).last("limit 1"));if(row==null){row=new ColdBatchArtifactEntity();row.setBatchId(batchId);row.setArtifactType("HOT_CLEANUP");row.setArtifactId(identity);row.setRelativePath(key);row.setSize(0L);row.setSha256("0".repeat(64));row.setWriteStatus("PENDING");artifacts.insert(row);}}}
 public long estimateBytes(long batchId){if(artifacts==null)return 1L;long total=0L;for(ColdBatchArtifactEntity row:artifacts.selectList(Wrappers.<ColdBatchArtifactEntity>lambdaQuery().eq(ColdBatchArtifactEntity::getBatchId,batchId).eq(ColdBatchArtifactEntity::getArtifactType,"HOT_CLEANUP"))){long size=row.getSize()==null?0L:row.getSize();if(size<0||Long.MAX_VALUE-total<size)throw new IllegalStateException("热备清理空间估算溢出");total+=size;}return Math.max(1L,total);}
 public synchronized Result cleanup(String batchId){Set<String> keys=fallback.remove(batchId);if(keys==null)throw new IllegalStateException("冷备批次未完成验证");int deleted=0;for(String key:keys){try{delete(key);deleted++;}catch(IOException e){throw new IllegalStateException("热备清理不完整: "+key,e);}}return new Result(batchId,deleted);}
 public Result cleanup(long batchId,String batchNo){if(artifacts==null)return cleanup(Long.toString(batchId));List<ColdBatchArtifactEntity> rows=artifacts.selectList(Wrappers.<ColdBatchArtifactEntity>lambdaQuery().eq(ColdBatchArtifactEntity::getBatchId,batchId).eq(ColdBatchArtifactEntity::getArtifactType,"HOT_CLEANUP").orderByAsc(ColdBatchArtifactEntity::getId));if(rows.isEmpty())throw new IllegalStateException("冷备批次未登记删除集合");int deleted=0;List<String> failed=new ArrayList<>();for(ColdBatchArtifactEntity row:rows){if("HOT_DELETED".equals(row.getWriteStatus())){deleted++;continue;}try{delete(row.getRelativePath());row.setWriteStatus("HOT_DELETED");row.setFailureMessage(null);deleted++;}catch(IOException e){row.setWriteStatus("FAILED");row.setFailureMessage(safe(e));failed.add(row.getRelativePath());}artifacts.updateById(row);}if(!failed.isEmpty())throw new IllegalStateException("热备清理不完整: "+failed);return new Result(batchNo,deleted);}
 /** 已通过冷备校验且管理员确认后直接删除热备对象，真正释放 NAS 容量。 */
 private void delete(String key)throws IOException{hot.delete(key);}
 private static long identity(String key){try{byte[] d=MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));return java.nio.ByteBuffer.wrap(d).getLong()&Long.MAX_VALUE;}catch(Exception e){throw new IllegalStateException(e);}}
 private static String safe(Exception e){String m=e.getMessage();return m==null?"文件清理失败":m.substring(0,Math.min(1000,m.length()));}
 public record Result(String batchId,int deleted){}
}
